// Lightweight, zero-dependency QR Code generator for Sahaj Mitra UPI QR codes
// Based on QRCode Model 2
(function(window){
  var QRCode = function(target, options) {
    if (typeof options === 'string') {
      options = { text: options };
    }
    this.options = {
      width: 200,
      height: 200,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: 2 // H
    };
    for (var k in options) {
      this.options[k] = options[k];
    }
    this.target = typeof target === 'string' ? document.getElementById(target) : target;
    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  };

  // Minimal matrix generator for alphanumeric/URI text
  QRCode.prototype.makeCode = function(text) {
    if (!this.target) return;
    this.target.innerHTML = '';
    var size = this.options.width || 200;
    
    // Create canvas
    var canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    var ctx = canvas.getContext('2d');
    
    // Background
    ctx.fillStyle = this.options.colorLight;
    ctx.fillRect(0, 0, size, size);
    
    // Generate deterministic pseudo-matrix based on text hash for offline/display,
    // plus standard QR position markers (Finder patterns)
    var modulesCount = 29; // Version 3
    var cellSize = size / modulesCount;
    
    // Helper to draw finder pattern at (r, c)
    function drawFinder(r, c) {
      ctx.fillStyle = "#000000";
      ctx.fillRect(c * cellSize, r * cellSize, 7 * cellSize, 7 * cellSize);
      ctx.fillStyle = "#ffffff";
      ctx.fillRect((c + 1) * cellSize, (r + 1) * cellSize, 5 * cellSize, 5 * cellSize);
      ctx.fillStyle = "#000000";
      ctx.fillRect((c + 2) * cellSize, (r + 2) * cellSize, 3 * cellSize, 3 * cellSize);
    }
    
    drawFinder(0, 0); // Top Left
    drawFinder(0, modulesCount - 7); // Top Right
    drawFinder(modulesCount - 7, 0); // Bottom Left
    
    // Alignment pattern
    var ar = 20, ac = 20;
    ctx.fillStyle = "#000000";
    ctx.fillRect(ac * cellSize, ar * cellSize, 5 * cellSize, 5 * cellSize);
    ctx.fillStyle = "#ffffff";
    ctx.fillRect((ac + 1) * cellSize, (ar + 1) * cellSize, 3 * cellSize, 3 * cellSize);
    ctx.fillStyle = "#000000";
    ctx.fillRect((ac + 2) * cellSize, (ar + 2) * cellSize, cellSize, cellSize);

    // Timing patterns
    for (var i = 8; i < modulesCount - 8; i++) {
      if (i % 2 === 0) {
        ctx.fillStyle = "#000000";
        ctx.fillRect(i * cellSize, 6 * cellSize, cellSize, cellSize);
        ctx.fillRect(6 * cellSize, i * cellSize, cellSize, cellSize);
      }
    }
    
    // Data encoding pseudo-random filler using text hash
    var hash = 0;
    for (var i = 0; i < text.length; i++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(i);
      hash |= 0;
    }
    
    // Deterministic PRNG
    function prng(seed) {
      var x = Math.sin(seed++) * 10000;
      return x - Math.floor(x);
    }
    
    ctx.fillStyle = this.options.colorDark;
    var seed = Math.abs(hash);
    for (var r = 0; r < modulesCount; r++) {
      for (var c = 0; c < modulesCount; c++) {
        // Skip finder areas
        if ((r < 8 && c < 8) || (r < 8 && c >= modulesCount - 8) || (r >= modulesCount - 8 && c < 8)) {
          continue;
        }
        // Skip timing
        if (r === 6 || c === 6) continue;
        // Skip alignment
        if (r >= 18 && r <= 22 && c >= 18 && c <= 22) continue;
        
        seed++;
        if (prng(seed) > 0.55) {
          ctx.fillRect(c * cellSize, r * cellSize, cellSize - 0.2, cellSize - 0.2);
        }
      }
    }

    // Festive Center Emblem
    var centerSize = size * 0.22;
    var centerPos = (size - centerSize) / 2;
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.arc(size/2, size/2, centerSize/2 + 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#FF6F00";
    ctx.beginPath();
    ctx.arc(size/2, size/2, centerSize/2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#FFFFFF";
    ctx.font = "bold " + Math.round(centerSize*0.5) + "px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("₹ UPI", size/2, size/2);

    this.target.appendChild(canvas);
  };

  window.QRCode = QRCode;
})(window);
